static u8 dac_to_rgb(u8 value) {
    if (value > 0x3F)
        value = 0x3F;
    /* The original writes six-bit values directly to VGA DAC port 3C9h.
     * Match the reference VGA proxy's bit expansion exactly: v86 retains
     * the low DAC bit in both newly exposed low RGB bits. */
    return (u8)((value << 2) | ((value & 1u) ? 3u : 0u));
}

void palette_set_scene(palette_scene_t scene) {
    const palette_color_t *src;
    const char *name;
    switch (scene) {
        case PALETTE_OPENING:  src = P1_OPENING;  name = "P1_Opening";  break;
        case PALETTE_TITLE:    src = P2_TITLE;    name = "P2_Title";    break;
        case PALETTE_GAMEPLAY: src = P3_GAMEPLAY; name = "P3_Gameplay"; break;
        default:
            platform_log("palette_set_scene: unknown scene %d", scene);
            memset(g_palette, 0, sizeof(g_palette));
            return;
    }
    memcpy(g_palette, src, sizeof(g_palette));
    platform_log("palette_set_scene: %s loaded (256 entries)", name);
}

void palette_set_opdmo_mcga(u16 ax) {
    if (ax >= (sizeof(OPDMO_MCGA_PALETTE_BASE) / sizeof(OPDMO_MCGA_PALETTE_BASE[0]))) {
        platform_log("palette_set_opdmo_mcga: unsupported AX=%u", ax);
        memset(g_palette, 0, sizeof(g_palette));
        return;
    }

    palette_set_opdmo_mcga_with_rgb0(
        ax,
        OPDMO_MCGA_PALETTE_BASE[ax][0],
        OPDMO_MCGA_PALETTE_BASE[ax][1],
        OPDMO_MCGA_PALETTE_BASE[ax][2]);
}

void palette_set_opdmo_mcga_with_rgb0(u16 ax, u8 r0, u8 g0, u8 b0) {
    if (ax >= (sizeof(OPDMO_MCGA_PALETTE_BASE) / sizeof(OPDMO_MCGA_PALETTE_BASE[0]))) {
        platform_log("palette_set_opdmo_mcga_with_rgb0: unsupported AX=%u", ax);
        memset(g_palette, 0, sizeof(g_palette));
        return;
    }

    u8 base_copy[48];
    memcpy(base_copy, OPDMO_MCGA_PALETTE_BASE[ax], sizeof(base_copy));
    base_copy[0] = r0;
    base_copy[1] = g0;
    base_copy[2] = b0;
    palette_set_opdmo_mcga_from_regs(base_copy);
}

void palette_set_opdmo_mcga_from_regs_with_rgb0(const u8 regs[48],
                                                u8 r0, u8 g0, u8 b0) {
    if (!regs) {
        memset(g_palette, 0, sizeof(g_palette));
        return;
    }

    u8 regs_copy[48];
    memcpy(regs_copy, regs, sizeof(regs_copy));
    regs_copy[0] = r0;
    regs_copy[1] = g0;
    regs_copy[2] = b0;
    palette_set_opdmo_mcga_from_regs(regs_copy);
}

void palette_set_opdmo_mcga_from_regs(const u8 regs[48]) {
    if (!regs) {
        memset(g_palette, 0, sizeof(g_palette));
        return;
    }

    for (int row = 0; row < 16; row++) {
        u8 bias_r = regs[row * 3 + 0];
        u8 bias_g = regs[row * 3 + 1];
        u8 bias_b = regs[row * 3 + 2];
        for (int col = 0; col < 16; col++) {
            u8 r = (u8)(regs[col * 3 + 0] + bias_r);
            u8 g = (u8)(regs[col * 3 + 1] + bias_g);
            u8 b = (u8)(regs[col * 3 + 2] + bias_b);
            g_palette[row * 16 + col] =
                (palette_color_t){dac_to_rgb(r), dac_to_rgb(g), dac_to_rgb(b)};
        }
    }
}

palette_color_t palette_opdmo_mcga_step_color(u16 ax, u8 step_row,
                                               u8 color_index,
                                               int override_rgb0,
                                               u8 r0, u8 g0, u8 b0) {
    if (ax >= (sizeof(OPDMO_MCGA_PALETTE_BASE) / sizeof(OPDMO_MCGA_PALETTE_BASE[0])))
        return (palette_color_t){0, 0, 0};

    u8 base_copy[48];
    memcpy(base_copy, OPDMO_MCGA_PALETTE_BASE[ax], sizeof(base_copy));
    if (override_rgb0) {
        base_copy[0] = r0;
        base_copy[1] = g0;
        base_copy[2] = b0;
    }

    const int row = step_row & 0x0F;
    const int col = color_index & 0x0F;
    u8 r = (u8)(base_copy[col * 3 + 0] + base_copy[row * 3 + 0]);
    u8 g = (u8)(base_copy[col * 3 + 1] + base_copy[row * 3 + 1]);
    u8 b = (u8)(base_copy[col * 3 + 2] + base_copy[row * 3 + 2]);
    return (palette_color_t){dac_to_rgb(r), dac_to_rgb(g), dac_to_rgb(b)};
}
